public enum FfiConnectionState: Equatable, Hashable {
    
    case disconnected
    case connectingDirect
    case connectingRelay
    case onlineDirect
    case onlineRelay





}

#if compiler(>=6)
extension FfiConnectionState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiConnectionState: FfiConverterRustBuffer {
    typealias SwiftType = FfiConnectionState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiConnectionState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .disconnected
        
        case 2: return .connectingDirect
        
        case 3: return .connectingRelay
        
        case 4: return .onlineDirect
        
        case 5: return .onlineRelay
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiConnectionState, into buf: inout [UInt8]) {
        switch value {
        
        
